import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.DQOulFGV.js";const q=JSON.parse('{"title":"常見問題 (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"zh-hant/guide/faq.md","filePath":"zh-hant/guide/faq.md"}'),n={name:"zh-hant/guide/faq.md"};function d(s,e,c,i,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="常見問題-faq" tabindex="-1">常見問題 (FAQ) <a class="header-anchor" href="#常見問題-faq" aria-label="Permalink to &quot;常見問題 (FAQ)&quot;">​</a></h1><p>整理了關於 KernelEX 的常見使用疑問與技術解答。</p><hr><h3 id="q1-為什麼像-top、htop、vim-這類程式在終端中無法正常顯示" tabindex="-1">Q1: 為什麼像 <code>top</code>、<code>htop</code>、<code>vim</code> 這類程式在終端中無法正常顯示？ <a class="header-anchor" href="#q1-為什麼像-top、htop、vim-這類程式在終端中無法正常顯示" aria-label="Permalink to &quot;Q1: 為什麼像 `top`、`htop`、`vim` 這類程式在終端中無法正常顯示？&quot;">​</a></h3><p><strong>A</strong>：KernelEX 是一個基於管道（Pipe 重定向 <code>stdin</code>/<code>stdout</code>/<code>stderr</code>）的圖形化執行輔助工具，<strong>不是</strong>基於 Linux 原生 PTY 偽終端的完整終端模擬器。因此，依賴 ncurses / 絕對游標移動定位的全螢幕互動式軟體無法正常渲染。KernelEX 主要針對自動化 Shell 腳本、後台服務程式、系統模組刷寫及批次處理工具。</p><hr><h3 id="q2-為什麼二進位程式需要以-so-命名" tabindex="-1">Q2: 為什麼二進位程式需要以 <code>.so</code> 命名？ <a class="header-anchor" href="#q2-為什麼二進位程式需要以-so-命名" aria-label="Permalink to &quot;Q2: 為什麼二進位程式需要以 `.so` 命名？&quot;">​</a></h3><p><strong>A</strong>：在 Android 平台中，通常只有特定受保護分區或 App 私有目錄具備二進位執行權限，將 ELF 原生可執行檔案命名為 <code>.so</code> 是 Magisk 模組與 Android 極客工具中通用的慣例。KernelEX 原生支援執行 <code>.so</code> 與 <code>.sh</code> 檔案，並在呼叫前自動補齊 <code>chmod 777</code>。</p><hr><h3 id="q3-任務在後台長時間執行時被系統清理怎麼辦" tabindex="-1">Q3: 任務在後台長時間執行時被系統清理怎麼辦？ <a class="header-anchor" href="#q3-任務在後台長時間執行時被系統清理怎麼辦" aria-label="Permalink to &quot;Q3: 任務在後台長時間執行時被系統清理怎麼辦？&quot;">​</a></h3><p><strong>A</strong>：</p><ol><li>請前往「設定」或權限檢查門，點擊「<strong>申請忽略電池最佳化</strong>」，將 KernelEX 新增至系統電池白名單；</li><li>在國內廠商自訂系統（如 HyperOS、OriginOS、ColorOS）中，建議在最近任務列將 KernelEX <strong>加鎖</strong>，並開啟「允許自啟動/關聯啟動」權限。</li></ol><hr><h3 id="q4-如何恢復預設字型" tabindex="-1">Q4: 如何恢復預設字型？ <a class="header-anchor" href="#q4-如何恢復預設字型" aria-label="Permalink to &quot;Q4: 如何恢復預設字型？&quot;">​</a></h3><p><strong>A</strong>：進入底欄「設定」頁面，找到「自訂軟體字型」卡片，點擊右側的設定圖示進入字型配置對話框，點擊「<strong>恢復預設字型</strong>」即可立即重設為內建預設字型。</p><hr><h3 id="q5-「新增到-kernelex」時的「獨立資料夾」有什麼作用" tabindex="-1">Q5: 「新增到 KernelEX」時的「獨立資料夾」有什麼作用？ <a class="header-anchor" href="#q5-「新增到-kernelex」時的「獨立資料夾」有什麼作用" aria-label="Permalink to &quot;Q5: 「新增到 KernelEX」時的「獨立資料夾」有什麼作用？&quot;">​</a></h3><p><strong>A</strong>：當多個腳本帶有同名資源檔案（例如 <code>config.json</code> 或輔助二進位）時，如果直接放入同一個目錄容易發生檔案覆蓋。開啟獨立資料夾功能後，KernelEX 會在 <code>/data/adb/KernelEX/</code> 下以 <code>[名稱]_[時間戳]</code> 自動建立子目錄進行隔離。</p>',18)])])}const g=o(n,[["render",d]]);export{q as __pageData,g as default};
